    private static long mexp(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    private static long modInverse(long a, long mod) {
        return mexp(a, mod - 2, mod);
    }

    private static long mul(long a, long b, long mod) {
        return (a * b) % mod;
    }
}

